angular.module("castra.core")
    .factory("campClock", campClock);

campClock.$inject = [ "$interval" ];

function campClock ($interval) {
    var time = "06:00";
    $interval(tick, 60000);

    return {
        now: now,
        tick: tick
    };

    function now () {
        return time;
    }

    function tick () {
        time = new Date().toTimeString().slice(0, 5);
    }
}

